
(()=>{"use strict";
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const en=()=>document.documentElement.lang==="en",tr=(he,x)=>en()?x:he;
async function api(path,opts={}){const init={credentials:"same-origin",...opts,headers:{"Content-Type":"application/json",...(opts.headers||{})}};if(opts.body&&typeof opts.body!=="string")init.body=JSON.stringify(opts.body);let r;try{r=await fetch(path,init)}catch(e){throw new Error(window.GmachDescribeNetworkError?window.GmachDescribeNetworkError(e):tr("לא ניתן להתחבר לשרת","Could not connect to the server"))}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(window.GmachDescribeHttpError?window.GmachDescribeHttpError(r,d):(d.error||tr("הפעולה נכשלה","Action failed")));return d}
function modal(){let d=$("#privacy-retention-dialog");if(!d){d=document.createElement("dialog");d.id="privacy-retention-dialog";d.className="modal modal-wide";document.body.append(d)}d.innerHTML='<button class="dialog-close" type="button" aria-label="'+tr("סגירה","Close")+'">×</button><h2>'+tr("מחיקה, פרטיות ושמירת נתונים","Deletion, privacy and retention")+'</h2><div data-retention-body></div>';$(".dialog-close",d).onclick=()=>d.close();return d}
async function openPanel(){
 const d=modal(),body=$("[data-retention-body]",d);body.innerHTML="<p>"+tr("טוענים...","Loading...")+"</p>";d.showModal();
 try{
  const x=await api("/api/admin/privacy-retention");
  body.innerHTML='<section><h3>'+tr("מדיניות שמירת נתונים","Data retention policies")+'</h3><div style="display:grid;gap:8px">'+(x.policies||[]).map(p=>'<form class="dashboard-row" data-policy="'+esc(p.policy_key)+'"><div><strong>'+esc(p.policy_key)+'</strong><p>'+tr("ימים לשמירה","Retention days")+'</p></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><input name="days" type="number" min="1" max="3650" value="'+Number(p.retention_days)+'" style="width:100px"><label><input name="enabled" type="checkbox" '+(p.enabled?"checked":"")+'> '+tr("פעיל","Enabled")+'</label><button class="button button-secondary button-small">'+tr("שמירה","Save")+'</button></div></form>').join("")+'</div></section><section><h3>'+tr("בקשות מחיקה בתהליך","Deletion requests in progress")+'</h3><div style="display:grid;gap:8px">'+((x.pending||[]).map(u=>'<article class="dashboard-row"><div><strong>'+esc(u.full_name)+'</strong><p>'+esc(u.email)+'</p><small>'+tr("גמ״חים בבעלות","Owned gmachs")+': '+Number(u.owned_organizations||0)+' · '+tr("השאלות פעילות","Active loans")+': '+Number(u.active_loans||0)+'</small></div><span class="status-chip">'+(u.deleted_at?tr("החשבון נמחק, ניקוי בתהליך","Account deleted, purge pending"):tr("בתקופת המתנה","Waiting period"))+'</span></article>').join("")||'<p>'+tr("אין בקשות פעילות.","No active requests.")+'</p>')+'</div></section><section><h3>'+tr("ריצות ניקוי אחרונות","Recent purge runs")+'</h3><div style="display:grid;gap:8px">'+((x.runs||[]).map(r=>'<article class="dashboard-row"><div><strong>'+esc(r.status)+'</strong><p>'+tr("שורות שנמחקו","Rows deleted")+': '+Number(r.rows_deleted||0)+' · '+tr("שורות שאונימיזציה","Rows anonymized")+': '+Number(r.rows_anonymized||0)+' · '+tr("קבצי מדיה","Media files")+': '+Number(r.media_deleted||0)+'</p><small>'+esc(r.created_at)+'</small></div></article>').join("")||'<p>'+tr("אין ריצות קודמות.","No previous runs.")+'</p>')+'</div></section><button class="button button-primary" type="button" data-run-purge>'+tr("הרצת ניקוי ו-retention עכשיו","Run purge and retention now")+'</button><p data-status role="status"></p>';
  $$("[data-policy]",body).forEach(f=>f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector("button");b.disabled=true;try{await api("/api/admin/privacy-retention/policies/"+encodeURIComponent(f.dataset.policy),{method:"PATCH",body:{retentionDays:Number(f.days.value),enabled:f.enabled.checked}});$("[data-status]",body).textContent=tr("המדיניות נשמרה.","Policy saved.")}catch(err){$("[data-status]",body).textContent=err.message}finally{b.disabled=false}});
  $("[data-run-purge]",body).onclick=async e=>{e.currentTarget.disabled=true;try{const result=await api("/api/admin/privacy-retention/run",{method:"POST",body:{}});$("[data-status]",body).textContent=tr("הניקוי הסתיים. משתמשים שנוקו: ","Cleanup completed. Purged users: ")+(result.purges||[]).filter(x=>!x.skipped).length;setTimeout(()=>openPanel(),700)}catch(err){$("[data-status]",body).textContent=err.message;e.currentTarget.disabled=false}};
 }catch(e){body.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}
}
function install(){
 const tab=$("#admin-tab"),actions=$("#dashboard-view .dashboard-actions");if(!tab||tab.hidden||!actions||actions.querySelector("[data-privacy-retention]"))return;
 const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.privacyRetention="1";b.textContent=tr("פרטיות ו-retention","Privacy & retention");b.onclick=openPanel;actions.prepend(b);
}
function init(){new MutationObserver(install).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:["hidden","lang"]});install()}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();
})();
